// Decode clusters.json and interconnection-queue.json fetched from GitHub.
// This node's direct input is the deals GET; the clusters GET is referenced by name.
const clustersResp = $("GitHub get clusters file").item.json;
const b64c = (clustersResp.content || "").replace(/\n/g, "");
const clustersRoot = JSON.parse(Buffer.from(b64c, "base64").toString("utf-8"));
const b64d = ($json.content || "").replace(/\n/g, "");
const dealsRoot = JSON.parse(Buffer.from(b64d, "base64").toString("utf-8"));
const dealIds = (dealsRoot.projects || []).map((p) => p.id);
if (!Array.isArray(clustersRoot.clusters) || clustersRoot.clusters.length < 1)
  throw new Error("clusters.json decode failed or empty");
if (dealIds.length < 1) throw new Error("interconnection-queue.json decode failed or empty");
return [{ json: { clusters: clustersRoot, dealIds, sha: clustersResp.sha } }];

// Parse Claude's patch, apply it to the current registry, then HARD-VALIDATE
// before anything can be committed. Any throw = abort: no commit, and the
// error output of this node feeds the abort ntfy alert.
const resp = $json;
let text = "";
if (Array.isArray(resp.content)) {
  for (const b of resp.content) { if (b.type === "text" && b.text) text += b.text; }
} else if (typeof resp.content === "string") {
  text = resp.content;
}
text = text.trim();
const s = text.indexOf("{");
const e = text.lastIndexOf("}");
if (s === -1 || e === -1) throw new Error("No JSON found in Claude response");
const patch = JSON.parse(text.slice(s, e + 1));

const decoded = $("Decode current files").item.json;
const prevRoot = decoded.clusters;
const prev = prevRoot.clusters;
const dealIds = new Set(decoded.dealIds);
const prevById = Object.fromEntries(prev.map((c) => [c.id, c]));
const today = new Date().toISOString().slice(0, 10);

const STATUS_RANK = { announced: 0, construction: 1, operational: 2 };
const SETTABLE = new Set(["name", "operator", "status", "gridRegion", "gpuCount", "chipType", "ratedPowerMW", "plannedPowerMW", "energySource", "workload", "linkedDeal", "onlineDate", "notes"]);
const ROW_FIELDS = ["id", "name", "operator", "status", "location", "gridRegion", "gpuCount", "chipType", "ratedPowerMW", "plannedPowerMW", "energySource", "workload", "linkedDeal", "onlineDate", "estimated", "sources", "notes"];
const isHttps = (u) => typeof u === "string" && /^https:\/\//.test(u);

const updates = Array.isArray(patch.updates) ? patch.updates : [];
const newClusters = Array.isArray(patch.newClusters) ? patch.newClusters : [];

if (updates.length > 30)
  throw new Error("suspicious churn: " + updates.length + " rows changed in one day; blocked for manual review");

// Clone rows so unchanged rows serialize byte-identical (key order preserved).
const merged = prev.map((c) => ({ ...c, estimated: [...(c.estimated || [])], sources: [...(c.sources || [])] }));
const mergedById = Object.fromEntries(merged.map((c) => [c.id, c]));
const changeLines = [];

for (const u of updates) {
  if (!u || typeof u.id !== "string" || !mergedById[u.id])
    throw new Error("update targets unknown cluster id: " + (u && u.id));
  const row = mergedById[u.id];
  const before = prevById[u.id];
  const set = u.set || {};
  const keys = Object.keys(set);
  if (keys.length === 0) throw new Error(u.id + ": empty set{} in update");
  for (const k of keys) {
    if (!SETTABLE.has(k)) throw new Error(u.id + ": field not updatable via patch: " + k);
  }
  if (!Array.isArray(u.addSources) || u.addSources.length < 1 || !u.addSources.every(isHttps))
    throw new Error(u.id + ": changed row missing https source(s)");
  if (!Array.isArray(u.estimated) || !u.estimated.every((f) => ROW_FIELDS.includes(f)))
    throw new Error(u.id + ": estimated[] missing or contains unknown field names");
  if ("status" in set) {
    if (!(set.status in STATUS_RANK)) throw new Error(u.id + ": invalid status " + set.status);
    if (STATUS_RANK[set.status] < STATUS_RANK[before.status])
      throw new Error(u.id + ": backward status transition " + before.status + " -> " + set.status + "; blocked for manual review");
  }
  for (const f of ["ratedPowerMW", "plannedPowerMW"]) {
    if (f in set && (typeof set[f] !== "number" || set[f] < 0 || set[f] > 15000))
      throw new Error(u.id + ": " + f + " out of range: " + set[f]);
  }
  if ("gpuCount" in set && set.gpuCount !== null && (typeof set.gpuCount !== "number" || set.gpuCount <= 0 || set.gpuCount > 5000000))
    throw new Error(u.id + ": gpuCount out of range: " + set.gpuCount);
  if ("linkedDeal" in set && set.linkedDeal !== null && !dealIds.has(set.linkedDeal))
    throw new Error(u.id + ": linkedDeal does not resolve in interconnection-queue.json: " + set.linkedDeal);
  Object.assign(row, set);
  row.estimated = u.estimated;
  for (const src of u.addSources) if (!row.sources.includes(src)) row.sources.push(src);
  const bits = keys.map((k) => k + ": " + JSON.stringify(before[k]) + " -> " + JSON.stringify(set[k]));
  changeLines.push(u.id + " | " + bits.join(", "));
}

for (const c of newClusters) {
  if (!c || typeof c.id !== "string" || !/^[a-z0-9][a-z0-9-]*$/.test(c.id))
    throw new Error("new cluster has bad id: " + (c && c.id));
  if (mergedById[c.id]) throw new Error("new cluster id already exists: " + c.id);
  for (const f of ROW_FIELDS) if (!(f in c)) throw new Error(c.id + ": new cluster missing field " + f);
  if (!(c.status in STATUS_RANK)) throw new Error(c.id + ": invalid status " + c.status);
  if (!c.location || typeof c.location.lat !== "number" || typeof c.location.lng !== "number" || typeof c.location.city !== "string" || typeof c.location.state !== "string")
    throw new Error(c.id + ": bad location");
  if (typeof c.ratedPowerMW !== "number" || c.ratedPowerMW < 0 || c.ratedPowerMW > 15000)
    throw new Error(c.id + ": ratedPowerMW out of range");
  if (typeof c.plannedPowerMW !== "number" || c.plannedPowerMW < 0 || c.plannedPowerMW > 15000)
    throw new Error(c.id + ": plannedPowerMW out of range");
  if (c.gpuCount !== null && (typeof c.gpuCount !== "number" || c.gpuCount <= 0 || c.gpuCount > 5000000))
    throw new Error(c.id + ": gpuCount out of range");
  if (!Array.isArray(c.sources) || c.sources.length < 1 || !c.sources.every(isHttps))
    throw new Error(c.id + ": new cluster needs at least one https source");
  if (!Array.isArray(c.estimated) || !c.estimated.every((f) => ROW_FIELDS.includes(f)))
    throw new Error(c.id + ": bad estimated[]");
  if (c.linkedDeal !== null && !dealIds.has(c.linkedDeal))
    throw new Error(c.id + ": linkedDeal does not resolve: " + c.linkedDeal);
  const ordered = {};
  for (const f of ROW_FIELDS) ordered[f] = c[f];
  merged.push(ordered);
  mergedById[c.id] = ordered;
  changeLines.push("NEW " + c.id + " (" + c.status + ", planned " + c.plannedPowerMW + " MW)");
}

// Whole-registry invariants.
if (merged.length < prev.length)
  throw new Error("cluster count shrank: " + merged.length + " vs " + prev.length);
for (const p of prev) if (!mergedById[p.id]) throw new Error("cluster disappeared: " + p.id);
for (const c of merged) {
  if (c.status === "operational" && !(c.ratedPowerMW > 0))
    throw new Error(c.id + ": operational cluster with 0 rated power");
  if (c.linkedDeal != null && !dealIds.has(c.linkedDeal))
    throw new Error(c.id + ": linkedDeal does not resolve: " + c.linkedDeal);
  if (!Array.isArray(c.sources) || c.sources.length < 1 || !c.sources.every(isHttps))
    throw new Error(c.id + ": row without https sources");
}
const prevPlanned = prev.reduce((a, c) => a + c.plannedPowerMW, 0);
const newPlanned = merged.reduce((a, c) => a + c.plannedPowerMW, 0);
if (prevPlanned > 0) {
  const swing = Math.abs(newPlanned - prevPlanned) / prevPlanned;
  if (swing > 0.15)
    throw new Error("total planned MW swung " + (swing * 100).toFixed(1) + "% in one day (" + prevPlanned + " -> " + newPlanned + " MW); blocked for manual review");
}

// lastRefreshed is what /api/clusters/metrics serves (root.lastRefreshed ?? null),
// format YYYY-MM-DD; bumped on every gate pass, methodology preserved verbatim.
const out = { lastRefreshed: today, methodology: prevRoot.methodology, clusters: merged };
const fileContent = JSON.stringify(out, null, 2) + "\n";

const summary =
  "GridTilt cluster registry refreshed " + today + ": " +
  updates.length + " updated, " + newClusters.length + " new, " + merged.length + " total, " +
  Math.round(newPlanned) + " MW planned.\n" +
  (changeLines.length ? changeLines.join("\n") : "No changes found; lastRefreshed bumped.");
const shortline = today + ": " + updates.length + " updated, " + newClusters.length + " new, " + merged.length + " total clusters";
return [{ json: { fileContent, summary, shortline } }];

// Base64-encode the validated file and assemble the GitHub commit payload.
const content = $json.fileContent;
const b64 = Buffer.from(content, "utf-8").toString("base64");
const sha = $("Decode current files").item.json.sha;
const commitBody = {
  message: "data: daily cluster refresh\n\n" + $json.shortline,
  content: b64,
  sha,
  branch: "main"
};
return [{ json: { commitBody, summary: $json.summary } }];
